["|cffffd100Alternate left and right|r  Each new text goes to the other side."] = "|cffffd100Links und rechts im Wechsel|r  Jeder neue Text geht auf die andere Seite.",
["|cffffd100Left|r  Every text goes left."] = "|cffffd100Links|r  Jeder Text geht nach links.",
["|cffffd100Right|r  Every text goes right."] = "|cffffd100Rechts|r  Jeder Text geht nach rechts.",
["|cffffd100Random side|r  Left or right, picked at random each time."] = "|cffffd100Zufällige Seite|r  Links oder rechts, jedes Mal zufällig gewählt.",
["|cffffd100Damage left, heals right|r  Damage goes left, heals go right."] = "|cffffd100Schaden links, Heilung rechts|r  Schaden geht nach links, Heilung nach rechts.",
["|cffffd100Damage right, heals left|r  Damage goes right, heals go left."] = "|cffffd100Schaden rechts, Heilung links|r  Schaden geht nach rechts, Heilung nach links.",
["|cff73bfffStraight or diagonal|r (movements that rise or fall)"] = "|cff73bfffGerade oder diagonal|r (Bewegungen, die steigen oder fallen)",
["|cffffd100Straight|r  Straight up or down."] = "|cffffd100Gerade|r  Gerade nach oben oder unten.",
["|cffffd100Diagonal left|r  Slants to the left as it travels."] = "|cffffd100Diagonal links|r  Neigt sich im Flug nach links.",
["|cffffd100Diagonal right|r  Slants to the right as it travels."] = "|cffffd100Diagonal rechts|r  Neigt sich im Flug nach rechts.",
["|cffffd100Diagonal to the side|r  Slants to the side picked under Side (alternate, random, damage left...)."] = "|cffffd100Diagonal zur Seite|r  Neigt sich zu der unter Seite gewählten Seite (Wechsel, zufällig, Schaden links...).",
["|cff73bfffHeight as it goes|r (movements that go sideways)"] = "|cff73bfffHöhe im Flug|r (Bewegungen, die seitwärts gehen)",
["|cffffd100At a random height|r  Each text starts a little higher or lower at random."] = "|cffffd100In zufälliger Höhe|r  Jeder Text beginnt zufällig etwas höher oder tiefer.",
["|cffffd100Level|r  Straight across, all at the same height."] = "|cffffd100Waagerecht|r  Gerade hinüber, alle in derselben Höhe.",
["|cffffd100Rising (diagonal up)|r  Climbs as it goes sideways."] = "|cffffd100Steigend (diagonal hoch)|r  Steigt, während es seitwärts geht.",
["|cffffd100Falling (diagonal down)|r  Drops as it goes sideways."] = "|cffffd100Fallend (diagonal runter)|r  Sinkt, während es seitwärts geht.",
["|cff73bfffAngle|r  How steep a diagonal is: 15, 30, 45 or 60 degrees."] = "|cff73bfffWinkel|r  Wie steil eine Diagonale ist: 15, 30, 45 oder 60 Grad.",
["|cffffd100Pop (SCT Sticky)|r  Pops a little bigger for a moment as it appears."] = "|cffffd100Ploppen (SCT Sticky)|r  Ploppt beim Erscheinen kurz etwas größer auf.",
["|cffffd100Slam in (MSBT Pow)|r  Starts twice as big and slams down to size."] = "|cffffd100Einschlagen (MSBT Pow)|r  Beginnt doppelt so groß und schlägt auf Größe herunter.",
["|cffffd100Slam and shake|r  Slams in like Pow, then shakes for half a second."] = "|cffffd100Einschlagen und Schütteln|r  Schlägt wie Pow ein, dann schüttelt es eine halbe Sekunde.",
["|cffffd100Shrink in from big (SCT Flash)|r  Starts twice as big and shrinks to size over a third of a second."] = "|cffffd100Von groß einschrumpfen (SCT Flash)|r  Beginnt doppelt so groß und schrumpft in einer Drittelsekunde auf Größe.",
["|cffffd100Swell and settle (Blizzard)|r  The game's own crit: swells fast, then settles a little bigger than a hit."] = "|cffffd100Anschwellen und setzen (Blizzard)|r  Der Krit des Spiels: schwillt schnell an, setzt sich dann etwas größer als ein Treffer.",
["|cffffd100Grow from small (Zoom)|r  Starts small and grows to size, with a little overshoot."] = "|cffffd100Klein anfangen und wachsen (Zoom)|r  Beginnt klein und wächst auf Größe, mit leichtem Überschwingen.",
["|cffffd100None, just bigger|r  No entrance: the crit is simply bigger than a hit."] = "|cffffd100Keine, nur größer|r  Kein Auftritt: Der Krit ist einfach größer als ein Treffer.",
["|cffffd100Vertical (SCT)|r  Straight up (or down) the area, one line after another."] = "|cffffd100Vertikal (SCT)|r  Gerade durch den Bereich nach oben (oder unten), Zeile für Zeile.",
["|cffffd100Rainbow arc (SCT)|r  Arcs out to the side and drops, like a rainbow."] = "|cffffd100Regenbogenbogen (SCT)|r  Fliegt im Bogen zur Seite und fällt, wie ein Regenbogen.",
["|cffffd100Horizontal (SCT)|r  Slides out sideways at a random height."] = "|cffffd100Horizontal (SCT)|r  Gleitet seitwärts heraus, in zufälliger Höhe.",
["|cffffd100Angled down (SCT)|r  Shoots out and down, shakes, holds, then drifts away."] = "|cffffd100Schräg nach unten (SCT)|r  Schießt heraus und nach unten, schüttelt, hält und treibt dann davon.",
["|cffffd100Angled up (SCT)|r  Shoots out and up, shakes, holds, then drifts up."] = "|cffffd100Schräg nach oben (SCT)|r  Schießt heraus und nach oben, schüttelt, hält und treibt dann nach oben.",
["|cffffd100Sprinkler (SCT)|r  Each new text leaves at the next angle of a fan."] = "|cffffd100Rasensprenger (SCT)|r  Jeder neue Text startet im nächsten Winkel eines Fächers.",
["|cffffd100HUD curved (SCT)|r  Runs up the side of a circle round the middle of the screen."] = "|cffffd100HUD gebogen (SCT)|r  Läuft an der Seite eines Kreises um die Bildschirmmitte hoch.",
["|cffffd100HUD angled (SCT)|r  Runs up a slanted line beside the middle of the screen."] = "|cffffd100HUD schräg (SCT)|r  Läuft an einer schrägen Linie neben der Bildschirmmitte hoch.",
["|cffffd100Parabola (MSBT)|r  Rises and bulges out half way up, MSBT style."] = "|cffffd100Parabel (MSBT)|r  Steigt und wölbt sich auf halber Höhe nach außen, im MSBT-Stil.",
["|cffffd100Static (MSBT / messages)|r  Stays put; new lines push the older ones along. Good for messages."] = "|cffffd100Statisch (MSBT / Meldungen)|r  Bleibt stehen; neue Zeilen schieben die älteren weiter. Gut für Meldungen.",
["|cffffd100Fountain (NameplateSCT)|r  Flies up out to the side and falls, like a fountain."] = "|cffffd100Fontäne (NameplateSCT)|r  Fliegt nach oben und zur Seite und fällt, wie eine Fontäne.",
["|cffffd100Rainfall (NameplateSCT)|r  Falls down from a random spot."] = "|cffffd100Regenfall (NameplateSCT)|r  Fällt von einer zufälligen Stelle herab.",
["|cffffd100Fireworks (NameplateSCT)|r  Bursts out in a random direction."] = "|cffffd100Feuerwerk (NameplateSCT)|r  Platzt in zufällige Richtung heraus.",
["|cffffd100Sway|r  Rises with a slow sway from side to side."] = "|cffffd100Schwanken|r  Steigt mit langsamem Hin- und Herschwanken.",
["|cffffd100Wave|r  Rises in a quicker wave."] = "|cffffd100Welle|r  Steigt in einer schnelleren Welle.",
["|cffffd100Zigzag|r  Rises zigzagging left and right."] = "|cffffd100Zickzack|r  Steigt im Zickzack nach links und rechts.",
["|cffffd100Spiral|r  Rises turning in a spiral."] = "|cffffd100Spirale|r  Steigt in einer Spirale drehend.",
["|cffffd100Bounce|r  Bounces up and out to the side."] = "|cffffd100Hüpfen|r  Hüpft nach oben und zur Seite.",
["|cffffd100Shockwave|r  Blasts out to the side fast, then slows."] = "|cffffd100Schockwelle|r  Schießt schnell zur Seite hinaus, dann wird sie langsamer.",
["|cffffd100Comet|r  Streaks out to the side in a curve."] = "|cffffd100Komet|r  Zieht in einer Kurve zur Seite.",
["|cffffd100Random mix|r  A different movement each time, picked at random."] = "|cffffd100Zufällige Mischung|r  Jedes Mal eine andere Bewegung, zufällig gewählt.",
["|cffffffff8 columns x 5 rows|r of 48 x 24 px frames - the whole raid 410 x 152 px"] = "|cffffffff8 Spalten x 5 Reihen|r aus Fenstern von 48 x 24 px - der ganze Schlachtzug 410 x 152 px",
}
for k, v in pairs(words) do if rawget(T, k) == nil then T[k] = v end end
